<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\User; use App\Models\ActivityLog; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException;
class AuthController extends Controller {
 public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required|string']);$user=User::where('email',$data['email'])->first();if(!$user||!$user->password||!Hash::check($data['password'],$user->password))throw ValidationException::withMessages(['email'=>['The provided credentials are incorrect.']]);$token=$user->createToken('northstar-admin')->plainTextToken;ActivityLog::create(['admin_id'=>$user->id,'action'=>'Administrator signed in','detail'=>'Password authentication succeeded','kind'=>'security']);return response()->json(['token'=>$token,'admin'=>$user]);}
 public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return response()->noContent();}
 public function me(Request $r){return $r->user();}
 public function updateProfile(Request $r){$user=$r->user();$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users,email,'.$user->id,'phone'=>'nullable|string|max:40','department'=>'nullable|string|max:120','notification_preferences'=>'sometimes|array','notification_preferences.*'=>'boolean']);$user->update($d);ActivityLog::create(['admin_id'=>$user->id,'action'=>'Administrator settings updated','detail'=>'Account profile or notification preferences were updated','kind'=>'security']);return $user->fresh();}
 public function password(Request $r){$d=$r->validate(['current_password'=>'required|string','password'=>'required|string|min:8|confirmed']);if(!Hash::check($d['current_password'],$r->user()->password))throw ValidationException::withMessages(['current_password'=>['The current password is incorrect.']]);$r->user()->update(['password'=>$d['password']]);ActivityLog::create(['admin_id'=>$r->user()->id,'action'=>'Administrator password changed','detail'=>'Account password was changed','kind'=>'security']);return response()->json(['message'=>'Password updated.']);}
}
